from cardio_1 import a, G
a('VEMS',[('V','Volume'),('E','Expiratoire'),('M','Maximal'),('S','par Seconde')],'Volume expiratoire maximal par seconde','<p>Volume d’air expiré pendant la première seconde d’une expiration forcée après une inspiration maximale. Équivalent anglais : FEV1. Grade la sévérité d’une obstruction.</p>','j45-spiro')
a('CVF',[('C','Capacité'),('V','Vitale'),('F','Forcée')],'Capacité vitale forcée','<p>Volume total expiré lors d’une expiration forcée et complète après une inspiration maximale. Équivalent anglais : FVC.</p>','j45-spiro')
a('LIN',[('L','Limite'),('I','Inférieure de la'),('N','Normale')],'Limite inférieure de la normale','<p>Cinquième percentile d’une population saine de même âge, sexe et taille (z-score −1,645). Seuil recommandé pour définir une obstruction.</p>','j45-lln')
a('DEP',[('D','Débit'),('E','Expiratoire de'),('P','Pointe')],'Débit expiratoire de pointe','<p>Débit maximal au début d’une expiration forcée, mesurable à domicile. Sert à prouver la variabilité et à guider le plan d’action.</p>','j45-pef')
a('GINA',[('G','Global'),('I','Initiative for'),('A','Asthma')],'Global Initiative for Asthma (Initiative mondiale pour l’asthme)','<p>Organisation qui publie chaque année la stratégie internationale de prise en charge de l’asthme ; version de référence ici : mai 2026.</p>')
a('FeNO',[('F','Fraction'),('e','expirée de'),('NO','monoxyde d’azote (Nitric Oxide)')],'Fraction expirée de monoxyde d’azote','<p>Marqueur de l’inflammation bronchique de type 2 induite par l’IL-13. Adulte : &gt; 50 ppb élevée, &lt; 25 ppb basse.</p>','j45-feno')
a('NO',[('N','Nitrogen (azote)'),('O','Oxide (monoxyde)')],'Monoxyde d’azote','<p>Gaz produit par les NO synthases ; dans les bronches, sa production par l’isoforme inductible reflète l’inflammation de type 2.</p>')
a('iNOS',[('i','inducible (inductible)'),('NOS','Nitric Oxide Synthase (NO synthase)')],'NO synthase inductible','<p>Enzyme épithéliale induite par l’IL-13 ; source principale du monoxyde d’azote expiré.</p>')
a('CSI',[('C','Corticostéroïde'),('S','(stéroïde)'),('I','Inhalé')],'Corticostéroïde inhalé','<p>Traitement anti-inflammatoire de base de l’asthme. Équivalent anglais : ICS.</p>','j45-d-ics')
a('ICS',[('I','Inhaled'),('C','Cortico'),('S','Steroid')],'Inhaled corticosteroid (corticostéroïde inhalé)','<p>Acronyme anglais utilisé par GINA, notamment dans « ICS-formotérol ».</p>','j45-d-ics')
a('BACA',[('B','Bêta-2'),('A','Agoniste de'),('C','Courte durée d’'),('A','Action')],'Bêta-2 agoniste de courte durée d’action','<p>Salbutamol, terbutaline : bronchodilatateurs de secours. Équivalent anglais : SABA.</p>','j45-d-saba')
a('SABA',[('S','Short-'),('A','Acting'),('B','Beta-2'),('A','Agonist')],'Short-acting beta-2 agonist (bêta-2 agoniste de courte durée d’action)','<p>GINA ne recommande plus le traitement par SABA seul chez l’adolescent et l’adulte.</p>','j45-d-saba')
a('BALA',[('B','Bêta-2'),('A','Agoniste de'),('L','Longue durée d’'),('A','Action')],'Bêta-2 agoniste de longue durée d’action','<p>Formotérol, salmétérol, vilanterol, indacatérol ; toujours associé à un corticostéroïde inhalé dans l’asthme. Équivalent anglais : LABA.</p>','j45-d-ics')
a('AMLA',[('A','AntiMuscarinique'),('L','de Longue durée d’'),('A','Action')],'Antimuscarinique de longue durée d’action','<p>Tiotropium : ajouté au palier 5 de l’asthme. Équivalent anglais : LAMA.</p>','j45-d-lama')
a('MART',[('M','Maintenance'),('A','And'),('R','Reliever'),('T','Therapy')],'Maintenance and reliever therapy (traitement d’entretien et de secours par le même inhalateur)','<p>Schéma par corticostéroïde inhalé et formotérol, pris quotidiennement et à la demande ; paliers 3 à 5 de la voie 1 de GINA.</p>','j45-d-icsf')
a('AIR',[('A','Anti-'),('I','Inflammatory'),('R','Reliever')],'Anti-inflammatory reliever (traitement de secours anti-inflammatoire)','<p>Corticostéroïde inhalé et formotérol pris à la demande seulement ; paliers 1–2 de la voie 1 de GINA.</p>','j45-d-icsf')
a('ACT',[('A','Asthma'),('C','Control'),('T','Test')],'Asthma Control Test (test de contrôle de l’asthme)','<p>Questionnaire en 5 questions, score 5 à 25 ; ≥ 20 : asthme bien contrôlé.</p>','j45-control')
a('ACQ-5',[('A','Asthma'),('C','Control'),('Q','Questionnaire'),('5','à 5 questions')],'Asthma Control Questionnaire à 5 questions','<p>Score moyen de 0 à 6 ; &lt; 0,75 : bien contrôlé ; &gt; 1,5 : non contrôlé.</p>','j45-control')
a('N-ERD',[('N','NSAID (anti-inflammatoire non stéroïdien)-'),('E','Exacerbated'),('R','Respiratory'),('D','Disease')],'Maladie respiratoire exacerbée par les anti-inflammatoires non stéroïdiens','<p>Asthme, polypose nasale et réaction à l’aspirine (triade de Widal).</p>','j45-nerd')
a('ABPA',[('A','Aspergillose'),('B','Broncho-'),('P','Pulmonaire'),('A','Allergique')],'Aspergillose bronchopulmonaire allergique','<p>Hypersensibilité à <i>Aspergillus</i> chez l’asthmatique ; IgE totales très élevées, bronchectasies centrales.</p>','j45-abpa')
a('IL-4',[('IL','InterLeukine'),('4','4')],'Interleukine 4','<p>Cytokine de type 2 : différenciation Th2, commutation des lymphocytes B vers les IgE.</p>','j45-t2')
a('IL-5',[('IL','InterLeukine'),('5','5')],'Interleukine 5','<p>Cytokine de type 2 : production, recrutement et survie des éosinophiles. Cible du mépolizumab et du reslizumab.</p>','j45-t2')
a('IL-13',[('IL','InterLeukine'),('13','13')],'Interleukine 13','<p>Cytokine de type 2 : mucus, hyperréactivité, induction de la NO synthase (FeNO).</p>','j45-t2')
a('IL-33',[('IL','InterLeukine'),('33','33')],'Interleukine 33','<p>Alarmine épithéliale qui active les ILC2 et les lymphocytes Th2.</p>','j45-t2')
a('IL-25',[('IL','InterLeukine'),('25','25')],'Interleukine 25','<p>Alarmine épithéliale de la famille IL-17, activatrice de l’immunité de type 2.</p>','j45-t2')
a('IL-4Rα',[('IL','InterLeukine'),('4','4'),('R','Récepteur'),('α','chaîne alpha')],'Chaîne alpha du récepteur de l’interleukine 4','<p>Sous-unité commune aux récepteurs de l’IL-4 et de l’IL-13 ; cible du dupilumab.</p>','j45-d-bio')
a('TSLP',[('T','Thymic'),('S','Stromal'),('L','Lymphopoietin (lymphopoïétine stromale thymique)'),('P','—')],'Thymic stromal lymphopoietin','<p>Alarmine épithéliale en amont de la cascade inflammatoire ; cible du tézépélumab.</p>','j45-d-bio')
a('ILC2',[('I','Innate (innées)'),('L','Lymphoid (lymphoïdes)'),('C','Cells (cellules)'),('2','de type 2')],'Cellules lymphoïdes innées de type 2','<p>Cellules sans récepteur spécifique d’antigène, activées par les alarmines, grandes productrices d’IL-5 et d’IL-13.</p>','j45-t2')
a('Th2',[('T','lymphocyte T'),('h','helper (auxiliaire)'),('2','de type 2')],'Lymphocyte T auxiliaire de type 2','<p>Lymphocyte T CD4 producteur d’IL-4, IL-5 et IL-13.</p>','j45-t2')
a('Th17',[('T','lymphocyte T'),('h','helper (auxiliaire)'),('17','producteur d’IL-17')],'Lymphocyte T auxiliaire de type 17','<p>Oriente une inflammation neutrophilique ; impliqué dans certains asthmes de type 2 faible.</p>')
a('FcεRI',[('Fc','fragment cristallisable'),('ε','epsilon (des IgE)'),('R','Récepteur'),('I','de type I (haute affinité)')],'Récepteur de haute affinité des IgE','<p>Présent sur les mastocytes et basophiles ; le pontage de deux IgE liées déclenche la dégranulation.</p>')
a('LTC₄',[('LT','LeucoTriène'),('C₄','C4 (à 4 doubles liaisons)')],'Leucotriène C4','<p>Leucotriène cystéinylé, puissant bronchoconstricteur.</p>')
a('LTD₄',[('LT','LeucoTriène'),('D₄','D4')],'Leucotriène D4','<p>Leucotriène cystéinylé ; ligand principal du récepteur CysLT1 bloqué par le montélukast.</p>')
a('LTE₄',[('LT','LeucoTriène'),('E₄','E4')],'Leucotriène E4','<p>Métabolite stable des leucotriènes cystéinylés, éliminé dans les urines.</p>')
a('PGD₂',[('PG','ProstaGlandine'),('D₂','D2')],'Prostaglandine D2','<p>Médiateur mastocytaire bronchoconstricteur et chimiotactique pour les cellules de type 2.</p>')
a('CysLT1',[('Cys','Cystéinyl-'),('LT','LeucoTriène'),('1','récepteur de type 1')],'Récepteur de type 1 des leucotriènes cystéinylés','<p>Cible du montélukast.</p>')
a('PKA',[('P','Protéine'),('K','Kinase'),('A','A (dépendante de l’AMPc)')],'Protéine kinase A','<p>Activée par l’AMPc ; médie le relâchement du muscle lisse bronchique après stimulation bêta-2.</p>')
a('AP-1',[('A','Activator'),('P','Protein'),('1','1')],'Activator protein 1','<p>Facteur de transcription pro-inflammatoire réprimé par le récepteur des glucocorticoïdes.</p>')
a('M3',[('M','Muscarinique'),('3','de sous-type 3')],'Récepteur muscarinique de sous-type 3','<p>Récepteur de l’acétylcholine du muscle lisse bronchique et des glandes ; couplé à Gq ; cible des antimuscariniques.</p>','j45-d-lama')
a('Gs',[('G','protéine G'),('s','stimulatrice')],'Protéine G stimulatrice','<p>Protéine G stimulatrice qui transmet le signal de récepteurs membranaires à l’adénylate cyclase, augmentant l’AMP cyclique. Les récepteurs bêta-1 cardiaques et bêta-2 bronchiques sont deux exemples ; l’effet final dépend du tissu. <a href="https://doi.org/10.1111/bph.70230" target="_blank" rel="noopener">Source : IUPHAR/BPS, Concise Guide 2025/26</a>.</p>')
a('Gq',[('G','protéine G'),('q','de la famille q')],'Protéine G de type q','<p>La famille Gq/11 transmet notamment le signal des récepteurs AT1 de l’angiotensine II et M3 muscariniques à la phospholipase C. Celle-ci forme l’inositol trisphosphate et le diacylglycérol ; le premier mobilise le calcium intracellulaire. La réponse dépend du récepteur et du tissu. <a href="https://doi.org/10.1111/bph.70230" target="_blank" rel="noopener">Source : IUPHAR/BPS, Concise Guide 2025/26</a>.</p>')
a('ORMDL3',[('ORM','ORMdl (homologue de la protéine ORM1 de levure)'),('DL','-Like (apparenté)'),('3','3')],'Gène ORMDL3','<p>Gène du locus 17q21 associé à l’asthme de l’enfant ; régule la synthèse des sphingolipides et le stress du réticulum endoplasmique.</p>')
a('GSDMB',[('GSDM','GaSDerMine'),('B','B')],'Gène de la gasdermine B','<p>Gène voisin d’ORMDL3 au locus 17q21, associé à l’asthme de l’enfant.</p>')
a('IL33',[('IL','InterLeukine'),('33','33 (gène)')],'Gène de l’interleukine 33','<p>Locus associé à l’asthme dans les études pangénomiques.</p>')
a('FLG',[('FLG','FiLaGgrine')],'Gène de la filaggrine','<p>Protéine de la barrière cutanée ; mutations perte de fonction associées à la dermatite atopique et à la marche atopique.</p>')
a('ADRB2',[('ADR','ADRénergique (récepteur)'),('B2','Bêta-2')],'Gène du récepteur bêta-2 adrénergique','<p>Polymorphismes étudiés pour la réponse aux bêta-2 agonistes, sans usage clinique.</p>')
a('ATS',[('A','American'),('T','Thoracic'),('S','Society')],'American Thoracic Society (Société thoracique américaine)','<p>Publie avec l’ERS les normes techniques de la fonction respiratoire.</p>')
a('GLI',[('G','Global'),('L','Lung Function'),('I','Initiative')],'Global Lung Function Initiative','<p>Valeurs de référence spirométriques multiethniques (2012) et « Global » 2022, indépendantes de l’origine ethnique.</p>','j45-lln')
a('DLCO',[('D','Diffusion (capacité de)'),('L','Lung (du poumon)'),('CO','pour le monoxyde de Carbone')],'Capacité de diffusion pulmonaire du monoxyde de carbone','<p>Mesure l’efficacité des échanges alvéolo-capillaires ; normale dans l’asthme, abaissée dans l’emphysème.</p>')
a('VR',[('V','Volume'),('R','Résiduel')],'Volume résiduel','<p>Air restant dans les poumons après une expiration maximale ; augmenté en cas de piégeage.</p>')
a('kPa',[('k','kilo'),('Pa','Pascal')],'Kilopascal','<p>Unité de pression ; 1 kPa = 7,5 mmHg.</p>')
a('AMM',[('A','Autorisation de'),('M','Mise sur le'),('M','Marché')],'Autorisation de mise sur le marché','<p>Autorisation délivrée en Suisse par Swissmedic pour une indication donnée ; une prescription hors de cette indication est dite « hors AMM » (off-label).</p>')
a('ACR',[('A','American'),('C','College of'),('R','Rheumatology')],'American College of Rheumatology','<p>Société savante américaine de rhumatologie ; critères de classification des vascularites avec l’EULAR.</p>')
a('SYGMA',[('SYGMA','nom d’essai « Symbicort Given as needed in Mild Asthma », non strictement lettre à lettre')],'Essais SYGMA 1 et 2 (2018)','<p>Budésonide-formotérol à la demande dans l’asthme léger : réduction des exacerbations sévères par rapport au salbutamol seul.</p>','j45-d-icsf')
a('START',[('START','nom d’essai (« Novel START ») sans développement lettre à lettre')],'Essai Novel START (2019)','<p>Essai pragmatique néo-zélandais : budésonide-formotérol à la demande versus salbutamol seul ou budésonide quotidien dans l’asthme léger.</p>','j45-d-icsf')
a('AMAZES',[('AMAZES','nom d’essai « AsthMA and AZithromycin Efficacy Study », non strictement lettre à lettre')],'Essai AMAZES (2017)','<p>Azithromycine trois fois par semaine : moins d’exacerbations dans l’asthme non contrôlé.</p>','j45-d-azi')
a('PrimoTinA-asthma',[('PrimoTinA','nom d’essai (tiotropium dans l’asthme primaire non contrôlé)'),('asthma','asthme')],'Essais PrimoTinA-asthma (2012)','<p>Tiotropium ajouté à une association corticostéroïde inhalé et BALA : meilleur VEMS, moins d’exacerbations.</p>','j45-d-lama')
a('CO',[('C','Carbone'),('O','Oxyde (monoxyde)')],'Monoxyde de carbone','<p>Gaz utilisé à très faible concentration pour mesurer la diffusion pulmonaire.</p>')
a('PGE₂',[('PG','ProstaGlandine'),('E₂','E2')],'Prostaglandine E2','<p>Prostaglandine bronchoprotectrice qui freine les mastocytes ; sa baisse sous aspirine participe à la N-ERD.</p>','j45-nerd')
a('F2α',[('F2','prostaglandine F2'),('α','alpha')],'Prostaglandine F2 alpha','<p>Prostaglandine bronchoconstrictrice ; son analogue carboprost est à éviter chez l’asthmatique.</p>')
a('PD20',[('P','Provocative (provoquante)'),('D','Dose'),('20','entraînant une chute de 20 % du VEMS')],'Dose provoquante 20','<p>Dose cumulée de méthacholine qui fait chuter le VEMS de 20 % ; plus elle est basse, plus l’hyperréactivité est marquée.</p>','j45-metha')
a('Dennie-Morgan',[('Dennie-Morgan','nom propre : Charles Dennie et David Morgan, dermatologues')],'Pli de Dennie-Morgan','<p>Pli cutané double sous la paupière inférieure, signe d’atopie chez l’enfant.</p>')
a('Charcot-Leyden',[('Charcot-Leyden','nom propre : Jean-Martin Charcot et Ernst von Leyden')],'Cristaux de Charcot-Leyden','<p>Cristaux de galectine-10 issus des éosinophiles, retrouvés dans l’expectoration de l’asthmatique.</p>')
for c,t in [('J45.0','Asthme à prédominance allergique'),('J45.1','Asthme non allergique'),('J45.8','Asthme associé (mixte)'),('J45.9','Asthme, sans précision')]:
    a(c,[(c,'code de la Classification internationale des maladies, 10e révision, modification allemande')],t,'<p>Code CIM-10-GM.</p>')
